import sys

def solve(N):
    result = []
    for i in range(N + 1):
        found = None
        for j in range(1, 10):
            if N % j == 0:  # j is a divisor of N
                step = N // j
                if i % step == 0:  # i is a multiple of N/j
                    found = j
                    break
        if found is not None:
            result.append(str(found))
        else:
            result.append('-')
    return ''.join(result)

